# exfil — staging and transfer indicators: recent archives in user-writable
# paths, cloud-sync roots, SMB sessions/opens, RDP session events. Read-only.
$cut=(Get-Date).ToUniversalTime().AddHours(-$SinceHours)
$A=@();try{foreach($d in (Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue)){foreach($sub in @('Desktop','Documents','Downloads')){$rt=Join-Path $d.FullName $sub;if(Test-Path $rt){foreach($f in (Get-ChildItem $rt -Recurse -Depth 2 -Include *.zip,*.7z,*.rar,*.tar,*.gz -File -ErrorAction SilentlyContinue)){if($f.LastWriteTimeUtc -gt $cut -and $A.Count -lt $Limit){$A+=[pscustomobject]@{path=$f.FullName;size=$f.Length;mtime=($f.LastWriteTimeUtc.ToString('o'))}}}}}}}catch{}
$C=@();try{foreach($d in (Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue)){foreach($pat in @('OneDrive*','Dropbox*','Google Drive*','GoogleDrive*','pCloud*','Box*')){foreach($p in (Get-ChildItem $d.FullName -Filter $pat -Directory -ErrorAction SilentlyContinue)){if($C.Count -lt $Limit){$C+=[pscustomobject]@{user=$d.Name;root=$p.Name;items_shallow=@(Get-ChildItem $p.FullName -ErrorAction SilentlyContinue).Count;mtime=($p.LastWriteTimeUtc.ToString('o'))}}}}}}catch{}
$S=@();try{foreach($s in (Get-SmbSession -ErrorAction Stop)){if($S.Count -lt 24){$S+=[pscustomobject]@{client=[string]$s.ClientComputerName;user=[string]$s.UserName;opens=$s.NumOpens;since=$s.CreationTime.ToString('o')}}}}catch{}
$O=0;try{$O=@(Get-SmbOpenFile -ErrorAction Stop).Count}catch{}
$R=@();try{$R=@(Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-TerminalServices-LocalSessionManager/Operational';Id=21,24,25} -MaxEvents 24 -ErrorAction Stop|ForEach-Object{[pscustomobject]@{t=$_.TimeCreated.ToUniversalTime().ToString('o');id=$_.Id;msg=$_.Message.Substring(0,[Math]::Min(90,$_.Message.Length))}})}catch{}
[pscustomobject]@{skill='exfil';host=$env:COMPUTERNAME;utc=(Get-Date).ToUniversalTime().ToString('o');window_hours=$SinceHours;recent_archives=$A;cloud_sync=$C;smb_sessions=$S;smb_open_files=$O;rdp_events=$R}|ConvertTo-Json -Compress -Depth 4
